import React from "react";
import "./ServiceCard.css";

export default function ServiceCard({ number, title, price, description, features, featured }) {
  return (
    <div className={`service-card reveal${featured ? " service-card--featured" : ""}`}>
      <div className="service-card-number">{number}</div>
      <h3 className="service-card-title">{title}</h3>
      <div className="service-card-price">{price}</div>
      <p className="service-card-desc">{description}</p>
      <ul className="service-features">
        {features.map((f) => (
          <li key={f} className="service-feature">
            <span className="feature-arrow">→</span>
            {f}
          </li>
        ))}
      </ul>
    </div>
  );
}
